function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'StringIterator' || args[0].length !== 1) return 'Start with StringIterator and one string.';
  const compressed = args[0][0];
  if (typeof compressed !== 'string' || compressed.length < 1 || compressed.length > 1000) return 'compressedString has 1 to 1000 characters.';
  if (!/^([A-Za-z][0-9]+)+$/.test(compressed)) return 'compressedString is letters, each followed by its count.';
  for (const group of compressed.match(/[A-Za-z][0-9]+/g)) {
    const repeat = Number(group.slice(1));
    if (repeat < 1 || repeat > 1000000000) return 'Each count is between 1 and 10^9.';
  }
  if (operations.length - 1 > 100) return 'At most 100 calls to next and hasNext.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'next' && operations[i] !== 'hasNext') return 'Only next and hasNext can follow the constructor.';
    if (args[i].length !== 0) return 'next and hasNext take no arguments.';
  }
  return null;
}

