class StringIterator {
  constructor(compressedString) {
    this.letters = [];
    this.counts = [];
    let i = 0;
    while (i < compressedString.length) {
      const letter = compressedString[i];
      i++;
      let count = 0;
      while (i < compressedString.length && compressedString[i] >= '0' && compressedString[i] <= '9') {
        count = count * 10 + Number(compressedString[i]);
        i++;
      }
      this.letters.push(letter);
      this.counts.push(count);
    }
    this.index = 0;
  }

  next() {
    if (!this.hasNext()) {
      return ' ';
    }
    const letter = this.letters[this.index];
    this.counts[this.index]--;
    if (this.counts[this.index] === 0) {
      this.index++;
    }
    return letter;
  }

  hasNext() {
    return this.index < this.letters.length;
  }
}

