class StringIterator {
  constructor(compressedString) {
    this.text = compressedString;
    this.used = 0;
  }
  // Find the character at position `used` by walking every group from the start.
  charAt(position) {
    const groups = this.text.match(/[A-Za-z]\d+/g);
    let seen = 0;
    for (const group of groups) {
      const repeat = parseInt(group.slice(1), 10);
      if (position < seen + repeat) return group[0];
      seen += repeat;
    }
    return null;
  }
  next() {
    const found = this.charAt(this.used);
    if (found === null) return ' ';
    this.used++;
    return found;
  }
  hasNext() {
    return this.charAt(this.used) !== null;
  }
}

