function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const pickLetter = () => (rand() < 0.5 ? alphabet[Math.floor(rand() * 4)] : alphabet[Math.floor(rand() * 52)]);
  const pickCount = () => {
    const r = rand();
    if (r < 0.6) return 1 + Math.floor(rand() * 3);
    if (r < 0.85) return 1 + Math.floor(rand() * 15);
    if (r < 0.95) return 1 + Math.floor(rand() * 1000000000);
    return 1000000000;
  };
  let compressed = '';
  let total = 0;
  const groups = size === 'large' ? 1000 : 1 + Math.floor(rand() * 4);
  for (let g = 0; g < groups; g++) {
    const count = size === 'large' && rand() < 0.97 ? 1 + Math.floor(rand() * 2) : pickCount();
    const piece = pickLetter() + count;
    if (compressed.length + piece.length > 1000) break;
    compressed += piece;
    total += count;
  }
  const operations = ['StringIterator'];
  const args = [[compressed]];
  const calls = size === 'large' ? 100 : 1 + Math.floor(rand() * Math.min(14, total + 4));
  const nextRate = 0.55 + rand() * 0.4;
  for (let i = 0; i < calls; i++) {
    operations.push(rand() < nextRate ? 'next' : 'hasNext');
    args.push([]);
  }
  return [operations, args];
}
